/**
 * `npm run gen` (ADR-0022): validates every modules/<id>/manifest.ts and writes the per-target generated
 * files. `--check` writes nothing and fails if a committed generated file is stale (CI).
 *
 * Outputs:
 *   packages/agent/src/generated/allowlist.ts     pure data: per-socket ops, managed files and units
 *   packages/shared/src/generated/permissions.ts  pure data: the permission catalogue
 *   modules/generated/registry.ts                 registry keys + template functions (imports module code)
 *   modules/generated/api.ts                      API route plugins
 *   modules/generated/watchers.ts                 watcher handlers
 *   packages/web/src/generated/modules.ts         i18n resources and lazy UI routes
 */
import { existsSync, readdirSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { manifestSchema, type ModuleManifest, type RegistryKeyDefinition } from '../manifest/index.ts';
import { catalogue, isCatalogued } from '../agent/catalogue.ts';
import { isImplementedOp } from '../agent/ops.ts';
import { staticFilter } from '../ldap/filter.ts';
import type { AgentSocket } from '../manifest/schema.ts';

type Manifest = ReturnType<typeof manifestSchema.parse>;

const HEADER =
  '// Generated by `npm run gen` from modules/*/manifest.ts. DO NOT EDIT.\n// SPDX-License-Identifier: AGPL-3.0-only\n';

export interface GenResult {
  files: Map<string, string>;
  issues: string[];
}

interface Loaded {
  dir: string;
  manifest: Manifest;
  keys: RegistryKeyDefinition[];
  i18n: Record<string, Record<'en' | 'de', unknown>>;
}

const I18N_FIELDS = new Set(['title', 'description', 'label', 'purpose']);

function lookup(obj: unknown, path: string): unknown {
  let cur: unknown = obj;
  for (const p of path.split('.')) {
    if (!cur || typeof cur !== 'object') return undefined;
    cur = (cur as Record<string, unknown>)[p];
  }
  return cur;
}

function collectI18nKeys(v: unknown, out: string[], field = ''): void {
  if (typeof v === 'string') {
    if (I18N_FIELDS.has(field)) out.push(v);
  } else if (Array.isArray(v)) {
    for (const x of v) collectI18nKeys(x, out, field);
  } else if (v && typeof v === 'object') {
    for (const [k, x] of Object.entries(v)) collectI18nKeys(x, out, k);
  }
}

async function load(root: string, issues: string[]): Promise<Loaded[]> {
  const modulesDir = join(root, 'modules');
  const out: Loaded[] = [];
  const dirs = readdirSync(modulesDir, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(modulesDir, d.name, 'manifest.ts')))
    .map((d) => d.name)
    .sort();
  for (const name of dirs) {
    const dir = join(modulesDir, name);
    const mod = (await import(pathToFileURL(join(dir, 'manifest.ts')).href)) as { default: ModuleManifest };
    const parsed = manifestSchema.safeParse(mod.default);
    if (!parsed.success) {
      for (const i of parsed.error.issues) issues.push(`${name}: manifest ${i.path.join('.')}: ${i.message}`);
      continue;
    }
    const manifest = parsed.data;
    if (manifest.id !== name) issues.push(`${name}: manifest id "${manifest.id}" must equal the directory name`);
    let keys: RegistryKeyDefinition[] = [];
    if (manifest.registry) {
      const entry = join(dir, manifest.registry.keysEntry);
      if (existsSync(entry)) {
        keys = ((await import(pathToFileURL(entry).href)) as { keys?: RegistryKeyDefinition[] }).keys ?? [];
      }
    }
    const i18n: Loaded['i18n'] = {};
    for (const ns of manifest.i18n.namespaces) {
      const files = {
        en: join(dir, 'i18n', ns === name ? 'en.json' : `${ns}.en.json`),
        de: join(dir, 'i18n', ns === name ? 'de.json' : `${ns}.de.json`),
      };
      const pair = {} as Record<'en' | 'de', unknown>;
      for (const lang of ['en', 'de'] as const) {
        try {
          pair[lang] = JSON.parse(readFileSync(files[lang], 'utf8'));
        } catch (e) {
          issues.push(`${name}: i18n ${relative(root, files[lang])}: ${e instanceof Error ? e.message : String(e)}`);
          pair[lang] = {};
        }
      }
      i18n[ns] = pair;
    }
    out.push({ dir, manifest, keys, i18n });
  }
  return out;
}

function validate(_root: string, mods: Loaded[], issues: string[]): void {
  const ids = new Set<string>();
  const allPerms = new Set<string>();
  const allKeys = new Set<string>();
  const allFiles = new Set<string>();
  for (const { manifest: m } of mods) for (const p of m.permissions) allPerms.add(p.name);

  for (const { dir, manifest: m, keys, i18n } of mods) {
    const id = m.id;
    const err = (msg: string): void => {
      issues.push(`${id}: ${msg}`);
    };
    if (ids.has(id)) err('duplicate module id');
    ids.add(id);
    const prefixed = (name: string): boolean => name.startsWith(`${id}.`);

    for (const p of m.permissions) {
      if (!prefixed(p.name)) err(`permission ${p.name} must start with "${id}."`);
      for (const imp of p.implies ?? []) if (!allPerms.has(imp)) err(`permission ${p.name} implies unknown ${imp}`);
    }
    for (const k of keys) {
      if (!prefixed(k.name)) err(`registry key ${k.name} must start with "${id}."`);
      if (allKeys.has(k.name)) err(`duplicate registry key ${k.name}`);
      allKeys.add(k.name);
      const ok = k.schema.safeParse(k.default);
      if (!ok.success) err(`registry key ${k.name}: default does not match its schema`);
    }
    const files = new Map((m.managed?.files ?? []).map((f) => [f.fileId, f]));
    for (const f of files.keys()) {
      if (!prefixed(f)) err(`managed file ${f} must start with "${id}."`);
      if (allFiles.has(f)) err(`duplicate managed file ${f}`);
      allFiles.add(f);
    }
    const units = new Map((m.managed?.units ?? []).map((u) => [u.unit, u]));
    for (const t of m.registry?.templates ?? []) {
      if (!files.has(t.fileId)) err(`template ${t.fileId} has no managed.files entry`);
      for (const r of t.reads) {
        const base = r.endsWith('.*') ? r.slice(0, -2) : r;
        if (!keys.some((k) => k.name === base || k.name.startsWith(base + '.')))
          err(`template ${t.fileId} reads unknown key ${r}`);
      }
      for (const h of t.onChange ?? []) {
        if (h.kind === 'service') {
          const u = units.get(h.unit);
          const action = h.action === 'try-reload-or-restart' ? 'restart' : h.action;
          if (!u?.allowed.includes(action))
            err(`template ${t.fileId} ${h.action}s unit ${h.unit}, which is not managed with that action`);
        } else if (!isCatalogued(h.op)) err(`template ${t.fileId} handler uses unknown agent op ${h.op}`);
      }
    }
    for (const use of m.agentOperations ?? []) {
      if (!isCatalogued(use.op)) {
        err(`agent operation ${use.op} is not in the catalogue (docs/design/agent-operations.md)`);
        continue;
      }
      const allowed: readonly AgentSocket[] = catalogue[use.op].sockets;
      for (const s of use.from)
        if (!allowed.includes(s)) err(`agent operation ${use.op} is not available on the ${s} socket`);
      if (!isImplementedOp(use.op))
        err(
          `agent operation ${use.op} is catalogued (phase ${String(catalogue[use.op].phase)}) but not implemented yet`,
        );
    }
    for (const w of m.watchers ?? []) {
      try {
        staticFilter(w.filter);
      } catch (e) {
        err(`watcher ${w.id}: ${e instanceof Error ? e.message : String(e)}`);
      }
    }
    // entry files exist and stay inside the module
    const entries: string[] = [];
    const collectEntries = (v: unknown, field = ''): void => {
      if (
        typeof v === 'string' &&
        (field === 'entry' || field.endsWith('Entry') || field === 'schema' || field === 'apply' || field === 'export')
      ) {
        if (v.startsWith('./')) entries.push(v);
      } else if (Array.isArray(v)) v.forEach((x) => collectEntries(x, field));
      else if (v && typeof v === 'object') for (const [k, x] of Object.entries(v)) collectEntries(x, k);
    };
    collectEntries(m);
    for (const e of entries) {
      const abs = resolve(dir, e);
      if (!abs.startsWith(dir)) err(`entry ${e} escapes the module directory`);
      else if (!existsSync(abs)) err(`entry ${e} does not exist`);
    }
    // i18n keys exist in en and de
    const i18nKeys: string[] = [];
    collectI18nKeys(m, i18nKeys);
    for (const k of keys) i18nKeys.push(k.description);
    for (const key of i18nKeys) {
      const [ns, path] = key.split(':') as [string, string];
      const res = i18n[ns];
      if (!res) {
        err(`i18n key ${key}: namespace ${ns} is not declared in i18n.namespaces`);
        continue;
      }
      for (const lang of ['en', 'de'] as const) {
        if (typeof lookup(res[lang], path) !== 'string') err(`i18n key ${key} missing in ${lang}`);
      }
    }
  }
}

const ts = (v: unknown): string => JSON.stringify(v, null, 2);

function render(root: string, mods: Loaded[]): Map<string, string> {
  const files = new Map<string, string>();
  const p = (...parts: string[]): string => join(root, ...parts);

  // agent allowlist: pure data
  const sockets: Record<AgentSocket, Set<string>> = { api: new Set(), watch: new Set(), cli: new Set() };
  const managedFiles: Record<string, unknown> = {};
  const managedUnits: Record<string, Set<string>> = {};
  for (const { manifest: m } of mods) {
    for (const use of m.agentOperations ?? []) for (const s of use.from) sockets[s].add(use.op);
    for (const f of m.managed?.files ?? []) {
      managedFiles[f.fileId] = {
        module: m.id,
        pathKey: f.pathKey,
        owner: f.owner,
        mode: parseInt(f.mode, 8),
        comment: f.comment,
      };
    }
    for (const u of m.managed?.units ?? []) {
      const set = (managedUnits[u.unit] ??= new Set());
      for (const a of u.allowed) set.add(a);
    }
  }
  const sorted = (s: Set<string>): string[] => [...s].sort();
  files.set(
    p('packages/agent/src/generated/allowlist.ts'),
    `${HEADER}\nexport const allowlist = ${ts({
      sockets: { api: sorted(sockets.api), watch: sorted(sockets.watch), cli: sorted(sockets.cli) },
      files: Object.fromEntries(Object.entries(managedFiles).sort(([a], [b]) => a.localeCompare(b))),
      units: Object.fromEntries(
        Object.entries(managedUnits)
          .sort(([a], [b]) => a.localeCompare(b))
          .map(([k, v]) => [k, sorted(v)]),
      ),
    })} as const;\n`,
  );

  // permissions: pure data
  const perms = mods
    .flatMap(({ manifest: m }) => m.permissions.map((x) => ({ module: m.id, ...x })))
    .sort((a, b) => a.name.localeCompare(b.name));
  files.set(
    p('packages/shared/src/generated/permissions.ts'),
    `${HEADER}\nexport const permissions = ${ts(perms)} as const;\n\nexport type PermissionName = (typeof permissions)[number]['name'];\n`,
  );

  // registry table (imports module code)
  const imports: string[] = [];
  const keyRefs: string[] = [];
  const tplRefs: string[] = [];
  for (const { manifest: m } of mods) {
    const v = m.id.replaceAll('-', '_');
    if (!m.registry) continue;
    imports.push(`import { keys as ${v}_keys } from '../${m.id}/${m.registry.keysEntry.slice(2)}';`);
    keyRefs.push(`...${v}_keys`);
    m.registry.templates.forEach((t, i) => {
      imports.push(`import ${v}_tpl${String(i)} from '../${m.id}/${t.entry.slice(2)}';`);
      const comment = m.managed?.files?.find((f) => f.fileId === t.fileId)?.comment ?? 'none';
      tplRefs.push(
        `  { module: ${ts(m.id)}, fileId: ${ts(t.fileId)}, render: ${v}_tpl${String(i)}, reads: ${JSON.stringify(t.reads)}, onChange: ${JSON.stringify(t.onChange ?? [])}, roles: ${JSON.stringify(t.roles)}, comment: ${ts(comment)} },`,
      );
    });
  }
  files.set(
    p('modules/generated/registry.ts'),
    `${HEADER}import type { RegistryKeyDefinition } from '@opendc/shared/manifest';\nimport type { GeneratedTemplate } from './types.ts';\n${imports.join('\n')}\n\nexport const registryKeys: RegistryKeyDefinition[] = [${keyRefs.join(', ')}];\n\nexport const templates: GeneratedTemplate[] = [\n${tplRefs.join('\n')}\n];\n`,
  );

  const apiImports: string[] = [];
  const apiRefs: string[] = [];
  const watchImports: string[] = [];
  const watchRefs: string[] = [];
  for (const { manifest: m } of mods) {
    const v = m.id.replaceAll('-', '_');
    if (m.api) {
      apiImports.push(`import ${v}_api from '../${m.id}/${m.api.entry.slice(2)}';`);
      apiRefs.push(
        `  { module: ${ts(m.id)}, plugin: ${v}_api, publicRoutes: ${JSON.stringify(m.api.publicRoutes ?? [])} },`,
      );
    }
    (m.watchers ?? []).forEach((w, i) => {
      watchImports.push(`import ${v}_w${String(i)} from '../${m.id}/${w.entry.slice(2)}';`);
      const { entry: _e, ...def } = w;
      watchRefs.push(`  { module: ${ts(m.id)}, handler: ${v}_w${String(i)}, ...${JSON.stringify(def)} },`);
    });
  }
  files.set(
    p('modules/generated/api.ts'),
    `${HEADER}import type { GeneratedApiModule } from './types.ts';\n${apiImports.join('\n')}\n\nexport const apiModules: GeneratedApiModule[] = [\n${apiRefs.join('\n')}\n];\n`,
  );
  files.set(
    p('modules/generated/watchers.ts'),
    `${HEADER}import type { GeneratedWatcher } from './types.ts';\n${watchImports.join('\n')}\n\nexport const watchers: GeneratedWatcher[] = [\n${watchRefs.join('\n')}\n];\n`,
  );

  // web: i18n resources and lazy routes
  const webImports: string[] = [];
  const en: string[] = [];
  const de: string[] = [];
  const routes: string[] = [];
  const nav: unknown[] = [];
  for (const { manifest: m } of mods) {
    for (const ns of m.i18n.namespaces) {
      const v = `${m.id.replaceAll('-', '_')}_${ns.replaceAll('-', '_')}`;
      const base = ns === m.id ? '' : `${ns}.`;
      webImports.push(`import ${v}_en from '../../../../modules/${m.id}/i18n/${base}en.json';`);
      webImports.push(`import ${v}_de from '../../../../modules/${m.id}/i18n/${base}de.json';`);
      en.push(`${ts(ns)}: ${v}_en`);
      de.push(`${ts(ns)}: ${v}_de`);
    }
    for (const r of m.ui?.routes ?? []) {
      routes.push(
        `  { module: ${ts(m.id)}, area: ${ts(r.area)}, path: ${ts(r.path)}, permission: ${ts(r.permission ?? null)}, component: lazy(() => import('../../../../modules/${m.id}/${r.entry.slice(2)}')) },`,
      );
    }
    for (const n of m.ui?.navigation ?? []) nav.push({ module: m.id, ...n });
  }
  files.set(
    p('packages/web/src/generated/modules.ts'),
    `${HEADER}import { lazy, type ComponentType, type LazyExoticComponent } from 'react';\n${webImports.join('\n')}\n\nexport const moduleI18n = {\n  en: { ${en.join(', ')} },\n  de: { ${de.join(', ')} },\n};\n\nexport interface GeneratedRoute {\n  module: string;\n  area: 'console' | 'portal' | 'self-service';\n  path: string;\n  permission: string | null;\n  component: LazyExoticComponent<ComponentType>;\n}\n\nexport const routes: GeneratedRoute[] = [\n${routes.join('\n')}\n];\n\nexport const navigation = ${ts(nav)};\n`,
  );
  return files;
}

export async function generate(root: string): Promise<GenResult> {
  const issues: string[] = [];
  const mods = await load(root, issues);
  validate(root, mods, issues);
  return { files: issues.length ? new Map<string, string>() : render(root, mods), issues };
}

async function main(): Promise<void> {
  const root = resolve(import.meta.dirname, '../../../..');
  const check = process.argv.includes('--check');
  const { files, issues } = await generate(root);
  if (issues.length) {
    console.error(`Module manifests are invalid (${String(issues.length)} issues):\n  ${issues.join('\n  ')}`);
    process.exit(1);
  }
  const stale: string[] = [];
  for (const [path, content] of files) {
    const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
    if (current === content) continue;
    if (check) stale.push(relative(root, path));
    else {
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, content);
      console.log(`wrote ${relative(root, path)}`);
    }
  }
  if (stale.length) {
    console.error(`Generated files are stale; run npm run gen and commit:\n  ${stale.join('\n  ')}`);
    process.exit(1);
  }
  if (check) console.log('generated files are up to date');
}

if (process.argv[1] && resolve(process.argv[1]) === resolve(import.meta.filename)) await main();
